const pptxgen = require("pptxgenjs");
const path = require("path");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const fs = require("fs");

// Icon rendering
const { FaBrain, FaWrench, FaRedo, FaExclamationTriangle } = require("react-icons/fa");
const { MdTimeline, MdTrendingUp, MdSecurity, MdScience } = require("react-icons/md");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - Midnight Executive with red accent for urgency
const C = {
  navy: "1A1F36",
  darkBg: "0F1323",
  cardBg: "1E2445",
  lightText: "FFFFFF",
  muted: "8B92B0",
  accent: "4F8EF7",
  accentAlt: "6C5CE7",
  warm: "F97316",
  subtle: "2A3158",
  tableBorder: "3A4170",
  ice: "CBD5E1",
};

const ASSETS = "/app/benchmark/assets";

async function build() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "METR";
  pres.title = "Measuring AI Ability to Complete Long Software Tasks";

  // Helper: consistent slide title
  function addSlideTitle(slide, title, opts = {}) {
    slide.addText(title, {
      x: 0.6, y: 0.35, w: 8.8, h: 0.7,
      fontSize: 22, fontFace: "Arial Black", color: C.lightText,
      bold: true, valign: "middle", margin: 0, ...opts,
    });
  }

  // ===== SLIDE 1: Title =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    // Left accent bar
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });

    slide.addText("Measuring AI Ability to\nComplete Long Software Tasks", {
      x: 0.6, y: 0.8, w: 8.5, h: 1.6,
      fontSize: 32, fontFace: "Arial Black", color: C.lightText,
      bold: true, valign: "middle", margin: 0, lineSpacingMultiple: 1.1,
    });

    slide.addText("Time Horizon Doubling Every 7 Months", {
      x: 0.6, y: 2.5, w: 8.5, h: 0.6,
      fontSize: 20, fontFace: "Arial", color: C.accent,
      bold: true, margin: 0,
    });

    // Headline stat
    slide.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 3.4, w: 5.5, h: 1.1, fill: { color: C.cardBg } });
    slide.addText([
      { text: "50% Time Horizon ", options: { fontSize: 14, color: C.ice } },
      { text: "doubles every ~7 months", options: { fontSize: 14, color: C.warm, bold: true } },
      { text: "\nFrom GPT-2 (2 sec) → o3 (~2 hours) in 6 years", options: { fontSize: 12, color: C.muted, breakLine: true } },
    ], { x: 0.85, y: 3.5, w: 5.0, h: 0.9, valign: "middle", margin: 0 });

    slide.addText("Thomas Kwa, Ben West, Joel Becker et al. — METR  |  arxiv.org/abs/2503.14499  |  March 2025", {
      x: 0.6, y: 5.0, w: 8.8, h: 0.4,
      fontSize: 9, fontFace: "Arial", color: C.muted, margin: 0,
    });
  }

  // ===== SLIDE 2: Metric Explained =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "A New Metric: 50% Task-Completion Time Horizon");

    slide.addText("The task duration (in skilled-human time) at which an AI model achieves a 50% success rate — providing an intuitive, human-grounded measure of autonomous capability.", {
      x: 0.6, y: 1.15, w: 9.0, h: 0.6,
      fontSize: 12, fontFace: "Arial", color: C.ice, margin: 0,
    });

    // 3-step flow
    const steps = [
      { num: "1", label: "Assemble Tasks", desc: "170 diverse software\n& research tasks" },
      { num: "2", label: "Measure", desc: "Human timing +\nAI success rates" },
      { num: "3", label: "Fit Model", desc: "Logistic regression\n→ 50% threshold" },
    ];
    steps.forEach((s, i) => {
      const bx = 0.6 + i * 3.1;
