      { name: "SWAA", count: "66", desc: "Single-step atomic actions", time: "1 sec – 30 sec" },
    ];
    sources.forEach((s, i) => {
      const bx = 0.6 + i * 3.1;
      slide.addShape(pres.shapes.RECTANGLE, { x: bx, y: 1.15, w: 2.7, h: 1.0, fill: { color: C.cardBg } });
      slide.addText(s.name, {
        x: bx + 0.15, y: 1.2, w: 1.3, h: 0.35,
