      });
      slide.addText(s.desc + "  |  " + s.time, {
        x: bx + 0.15, y: 1.6, w: 2.4, h: 0.4,
        fontSize: 10, fontFace: "Arial", color: C.muted, margin: 0,
      });
    });

    // Example tasks table
    const hdrOpts = { fill: { color: C.accent }, color: C.lightText, bold: true, fontSize: 11, fontFace: "Arial", align: "left", valign: "middle" };
    const cellOpts = { fill: { color: C.cardBg }, color: C.ice, fontSize: 10, fontFace: "Arial", valign: "middle", border: { pt: 0.5, color: C.tableBorder } };
    const cellOptsAlt = { ...cellOpts, fill: { color: C.subtle } };

    const tableRows = [
      [
        { text: "Task Family", options: { ...hdrOpts } },
        { text: "Human Time", options: { ...hdrOpts } },
        { text: "Description", options: { ...hdrOpts } },
