      [
        { text: "find_shell_script", options: { ...cellOpts, fontFace: "Consolas", fontSize: 9 } },
        { text: "3 seconds", options: { ...cellOpts } },
        { text: 'Multiple choice: "Which file is a shell script?"', options: { ...cellOpts } },
      ],
      [
        { text: "wikipedia_research", options: { ...cellOptsAlt, fontFace: "Consolas", fontSize: 9 } },
        { text: "1 minute", options: { ...cellOptsAlt } },
        { text: "Research simple factual information from Wikipedia", options: { ...cellOptsAlt } },
      ],
      [
        { text: "oxdna_simple", options: { ...cellOpts, fontFace: "Consolas", fontSize: 9 } },
        { text: "9 minutes", options: { ...cellOpts } },
        { text: "Detect and fix bug in molecular dynamics simulation input files", options: { ...cellOpts } },
      ],
      [
        { text: "munge_data", options: { ...cellOptsAlt, fontFace: "Consolas", fontSize: 9 } },
        { text: "56 minutes", options: { ...cellOptsAlt } },
        { text: "Write Python script to transform JSON data by inferring conversion rules", options: { ...cellOptsAlt } },
      ],
      [
        { text: "cuda_backtesting", options: { ...cellOpts, fontFace: "Consolas", fontSize: 9 } },
        { text: "8 hours", options: { ...cellOpts } },
        { text: "Implement custom CUDA kernels for 30x speedup of backtesting tool", options: { ...cellOpts } },
      ],
    ];

    slide.addTable(tableRows, {
      x: 0.6, y: 2.45, w: 8.8,
