    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "A New Metric: 50% Task-Completion Time Horizon");

    slide.addText("The task duration (in skilled-human time) at which an AI model achieves a 50% success rate — providing an intuitive, human-grounded measure of autonomous capability.", {
      x: 0.6, y: 1.15, w: 9.0, h: 0.6,
      fontSize: 12, fontFace: "Arial", color: C.ice, margin: 0,
    });

    // 3-step flow
    const steps = [
      { num: "1", label: "Assemble Tasks", desc: "170 diverse software\n& research tasks" },
      { num: "2", label: "Measure", desc: "Human timing +\nAI success rates" },
      { num: "3", label: "Fit Model", desc: "Logistic regression\n→ 50% threshold" },
    ];
    steps.forEach((s, i) => {
      const bx = 0.6 + i * 3.1;
      slide.addShape(pres.shapes.RECTANGLE, { x: bx, y: 1.95, w: 2.7, h: 1.3, fill: { color: C.cardBg } });
      slide.addText(s.num, {
        x: bx + 0.15, y: 2.0, w: 0.5, h: 0.5,
        fontSize: 20, fontFace: "Arial Black", color: C.accent, bold: true, margin: 0,
      });
      slide.addText(s.label, {
        x: bx + 0.6, y: 2.05, w: 1.9, h: 0.4,
        fontSize: 14, fontFace: "Arial", color: C.lightText, bold: true, margin: 0,
      });
      slide.addText(s.desc, {
        x: bx + 0.15, y: 2.55, w: 2.4, h: 0.6,
        fontSize: 11, fontFace: "Arial", color: C.muted, margin: 0,
      });
      if (i < 2) {
        slide.addText("→", {
          x: bx + 2.75, y: 2.2, w: 0.35, h: 0.5,
          fontSize: 20, color: C.accent, align: "center", valign: "middle", margin: 0,
        });
      }
    });

    // figure_2
    slide.addImage({ path: path.join(ASSETS, "figure_2.jpg"), x: 0.6, y: 3.5, w: 8.8, h: 1.9, sizing: { type: "contain", w: 8.8, h: 1.9 } });
  }

  // ===== SLIDE 3: Task Suite Overview (TABLE) =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "170 Tasks Spanning 3 Seconds to 8 Hours of Human Effort");

    // Source composition cards
    const sources = [
      { name: "HCAST", count: "97", desc: "Diverse software tasks", time: "1 min – 30 hrs" },
      { name: "RE-Bench", count: "7", desc: "ML research engineering", time: "8 hrs each" },
      { name: "SWAA", count: "66", desc: "Single-step atomic actions", time: "1 sec – 30 sec" },
    ];
    sources.forEach((s, i) => {
      const bx = 0.6 + i * 3.1;
      slide.addShape(pres.shapes.RECTANGLE, { x: bx, y: 1.15, w: 2.7, h: 1.0, fill: { color: C.cardBg } });
      slide.addText(s.name, {
        x: bx + 0.15, y: 1.2, w: 1.3, h: 0.35,
        fontSize: 14, fontFace: "Arial Black", color: C.accent, bold: true, margin: 0,
      });
      slide.addText(s.count + " tasks", {
        x: bx + 1.5, y: 1.2, w: 1.0, h: 0.35,
        fontSize: 12, fontFace: "Arial", color: C.warm, bold: true, align: "right", margin: 0,
      });
      slide.addText(s.desc + "  |  " + s.time, {
        x: bx + 0.15, y: 1.6, w: 2.4, h: 0.4,
        fontSize: 10, fontFace: "Arial", color: C.muted, margin: 0,
      });
    });

    // Example tasks table
    const hdrOpts = { fill: { color: C.accent }, color: C.lightText, bold: true, fontSize: 11, fontFace: "Arial", align: "left", valign: "middle" };
    const cellOpts = { fill: { color: C.cardBg }, color: C.ice, fontSize: 10, fontFace: "Arial", valign: "middle", border: { pt: 0.5, color: C.tableBorder } };
    const cellOptsAlt = { ...cellOpts, fill: { color: C.subtle } };

    const tableRows = [
      [
        { text: "Task Family", options: { ...hdrOpts } },
        { text: "Human Time", options: { ...hdrOpts } },
        { text: "Description", options: { ...hdrOpts } },
      ],
      [
        { text: "find_shell_script", options: { ...cellOpts, fontFace: "Consolas", fontSize: 9 } },
        { text: "3 seconds", options: { ...cellOpts } },
        { text: 'Multiple choice: "Which file is a shell script?"', options: { ...cellOpts } },
      ],
      [
        { text: "wikipedia_research", options: { ...cellOptsAlt, fontFace: "Consolas", fontSize: 9 } },
        { text: "1 minute", options: { ...cellOptsAlt } },
        { text: "Research simple factual information from Wikipedia", options: { ...cellOptsAlt } },
      ],
      [
        { text: "oxdna_simple", options: { ...cellOpts, fontFace: "Consolas", fontSize: 9 } },
        { text: "9 minutes", options: { ...cellOpts } },
        { text: "Detect and fix bug in molecular dynamics simulation input files", options: { ...cellOpts } },
      ],
      [
        { text: "munge_data", options: { ...cellOptsAlt, fontFace: "Consolas", fontSize: 9 } },
        { text: "56 minutes", options: { ...cellOptsAlt } },
        { text: "Write Python script to transform JSON data by inferring conversion rules", options: { ...cellOptsAlt } },
      ],
      [
        { text: "cuda_backtesting", options: { ...cellOpts, fontFace: "Consolas", fontSize: 9 } },
        { text: "8 hours", options: { ...cellOpts } },
        { text: "Implement custom CUDA kernels for 30x speedup of backtesting tool", options: { ...cellOpts } },
      ],
    ];

    slide.addTable(tableRows, {
      x: 0.6, y: 2.45, w: 8.8,
      colW: [2.2, 1.3, 5.3],
      rowH: [0.35, 0.4, 0.4, 0.4, 0.4, 0.4],
      margin: [3, 6, 3, 6],
    });

    slide.addText("800+ human baselines  |  2,529 hours of human timing data collected", {
      x: 0.6, y: 5.0, w: 8.8, h: 0.35,
      fontSize: 10, fontFace: "Arial", color: C.muted, margin: 0,
    });
  }

  // ===== SLIDE 4: Exponential Trend (CHART figure) =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "Exponential Trend: 2 Seconds → ~2 Hours in 6 Years");

    // Key stats row
    const stats = [
      { val: "~207 days", label: "Doubling Time" },
      { val: "R² = 0.97", label: "Fit Quality" },
      { val: "6 years", label: "GPT-2 → o3" },
    ];
    stats.forEach((s, i) => {
      const bx = 0.6 + i * 2.2;
      slide.addText(s.val, {
        x: bx, y: 1.15, w: 2.0, h: 0.4,
        fontSize: 18, fontFace: "Arial Black", color: C.warm, bold: true, margin: 0,
      });
      slide.addText(s.label, {
        x: bx, y: 1.55, w: 2.0, h: 0.25,
        fontSize: 10, fontFace: "Arial", color: C.muted, margin: 0,
      });
    });

    // Main chart image
    slide.addImage({ path: path.join(ASSETS, "figure_1.jpg"), x: 0.4, y: 1.95, w: 9.2, h: 3.4, sizing: { type: "contain", w: 9.2, h: 3.4 } });

    // Model milestone labels
    slide.addText("GPT-2 ~2s  →  GPT-4 ~5min  →  Claude 3.5 Sonnet ~28min  →  o3 ~1h50m", {
      x: 0.6, y: 5.15, w: 8.8, h: 0.3,
      fontSize: 9, fontFace: "Consolas", color: C.ice, margin: 0, align: "center",
    });
  }

  // ===== SLIDE 5: Per-Model Success Curves =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "Success Probability Drops Sharply with Task Length");

    slide.addText("Each curve shows one model's success rate vs. human-time task duration. Frontier models push the curve rightward — succeeding at longer tasks.", {
      x: 0.6, y: 1.15, w: 9.0, h: 0.5,
      fontSize: 12, fontFace: "Arial", color: C.ice, margin: 0,
    });

    slide.addImage({ path: path.join(ASSETS, "figure_3.jpg"), x: 0.3, y: 1.75, w: 9.4, h: 3.6, sizing: { type: "contain", w: 9.4, h: 3.6 } });

    slide.addText("Claude 3.7 Sonnet: 54 min  |  o3: ~1h 50min  |  80% horizon ≈ 5× shorter than 50%", {
      x: 0.6, y: 5.15, w: 8.8, h: 0.3,
      fontSize: 9, fontFace: "Arial", color: C.muted, margin: 0, align: "center",
    });
  }

  // ===== SLIDE 6: Drivers of Progress =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "Reasoning, Tool Use, and Error Recovery Drive Growth");

    const icons = await Promise.all([
      iconToBase64Png(FaBrain, "#4F8EF7", 256),
      iconToBase64Png(FaWrench, "#F97316", 256),
      iconToBase64Png(FaRedo, "#6C5CE7", 256),
      iconToBase64Png(FaExclamationTriangle, "#EF4444", 256),
    ]);

    const drivers = [
      { icon: icons[0], title: "Improved Logical Reasoning", desc: "Models demonstrate stronger multi-step reasoning chains and planning ability across complex software tasks." },
      { icon: icons[1], title: "Better Tool Use", desc: "More effective use of code execution, file manipulation, and external tools in agentic workflows." },
      { icon: icons[2], title: "Reliability & Self-Awareness", desc: "Greater consistency in task execution and ability to adapt when encountering mistakes or dead ends." },
      { icon: icons[3], title: "Limitation: Messy Tasks", desc: "Performance remains notably lower on less structured, ambiguous tasks that lack clear specifications." },
    ];

    drivers.forEach((d, i) => {
      const row = Math.floor(i / 2);
      const col = i % 2;
      const bx = 0.6 + col * 4.6;
      const by = 1.3 + row * 1.9;

      slide.addShape(pres.shapes.RECTANGLE, { x: bx, y: by, w: 4.2, h: 1.5, fill: { color: C.cardBg } });
      slide.addImage({ data: d.icon, x: bx + 0.2, y: by + 0.25, w: 0.45, h: 0.45 });
      slide.addText(d.title, {
        x: bx + 0.8, y: by + 0.15, w: 3.2, h: 0.4,
        fontSize: 13, fontFace: "Arial", color: C.lightText, bold: true, margin: 0,
      });
      slide.addText(d.desc, {
        x: bx + 0.2, y: by + 0.7, w: 3.8, h: 0.7,
        fontSize: 10, fontFace: "Arial", color: C.muted, margin: 0,
      });
    });
  }

  // ===== SLIDE 7: Extrapolation =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "Extrapolation: Month-Long Task Automation by 2028–2031");

    // Big stat
    slide.addText("167", {
      x: 0.6, y: 1.3, w: 2.5, h: 0.8,
      fontSize: 52, fontFace: "Arial Black", color: C.warm, bold: true, margin: 0,
    });
    slide.addText("work hours\n(~1 month)", {
      x: 0.6, y: 2.1, w: 2.5, h: 0.5,
      fontSize: 12, fontFace: "Arial", color: C.muted, margin: 0,
    });

    // Timeline bar
    slide.addShape(pres.shapes.RECTANGLE, { x: 3.5, y: 1.4, w: 6.0, h: 0.08, fill: { color: C.subtle } });
    const milestones = [
      { x: 3.5, label: "2025\n~2 hrs", color: C.accent },
      { x: 5.8, label: "2028\nEarliest", color: C.warm },
      { x: 8.1, label: "2031\nLatest", color: C.warm },
    ];
    milestones.forEach(m => {
      slide.addShape(pres.shapes.OVAL, { x: m.x - 0.08, y: 1.32, w: 0.25, h: 0.25, fill: { color: m.color } });
      slide.addText(m.label, {
        x: m.x - 0.5, y: 1.65, w: 1.2, h: 0.55,
        fontSize: 10, fontFace: "Arial", color: C.ice, align: "center", margin: 0,
      });
    });

    // Key points
    const points = [
      "2023–2025 growth rate is ~20% faster than the overall 2019–2025 rate, suggesting possible acceleration.",
      "Naive extrapolation of the exponential trend places the 1-month time horizon (167 work hours) between mid-2028 and mid-2031.",
      "External validity remains an open question — supplementary experiments found little evidence that trends are slower on more realistic tasks.",
    ];
    points.forEach((p, i) => {
      slide.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 2.85 + i * 0.85, w: 8.8, h: 0.7, fill: { color: C.cardBg } });
      slide.addText(p, {
        x: 0.8, y: 2.9 + i * 0.85, w: 8.4, h: 0.6,
        fontSize: 11, fontFace: "Arial", color: C.ice, margin: 0, valign: "middle",
      });
    });
  }

  // ===== SLIDE 8: Takeaways =====
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.accent } });
    addSlideTitle(slide, "Takeaways: Exponential Growth Demands Proactive Safety Governance");

    const takeaways = [
      { num: "1", text: "50% time horizon is a robust, intuitive metric for tracking AI autonomy — R² = 0.97 over 6 years of model releases." },
      { num: "2", text: "Doubling every ~7 months with possible acceleration since 2024 — the pace may be increasing." },
      { num: "3", text: "Current frontier at ~2 hours of human-equivalent autonomous work (o3, early 2025)." },
      { num: "4", text: "External validity remains open — tasks may not perfectly represent real-world intellectual labor distributions." },
      { num: "5", text: "Key limitations: poor performance on unstructured tasks; uncertain generalization to real-world job distributions." },
    ];

    takeaways.forEach((t, i) => {
      const by = 1.2 + i * 0.82;
      slide.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: by, w: 8.8, h: 0.68, fill: { color: C.cardBg } });
      slide.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: by, w: 0.06, h: 0.68, fill: { color: C.accent } });
      slide.addText(t.num, {
        x: 0.85, y: by + 0.08, w: 0.4, h: 0.4,
        fontSize: 16, fontFace: "Arial Black", color: C.accent, bold: true, margin: 0, align: "center",
      });
      slide.addText(t.text, {
        x: 1.35, y: by + 0.05, w: 7.9, h: 0.58,
        fontSize: 11, fontFace: "Arial", color: C.ice, margin: 0, valign: "middle",
      });
    });

    slide.addText("Source: Kwa et al., METR, March 2025  |  arxiv.org/abs/2503.14499", {
      x: 0.6, y: 5.15, w: 8.8, h: 0.3,
      fontSize: 9, fontFace: "Arial", color: C.muted, margin: 0, align: "center",
    });
  }

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Done: /app/output/final_deck.pptx");
}

build().catch(e => { console.error(e); process.exit(1); });

